        '<b>전용 칩은 중고 시장이 없다.</b> 극단적 사례가 비트코인 채굴 칩이다. 한때 전체 채굴력의 70%를 담당하던 Antminer S9은 신형이 나오고 보상이 줄자 전기료도 못 건지는 고철이 됐다.',
        '<b>그래도 빅테크가 몰빵하는 이유.</b> 안 바뀌는 영역이 거대하다. 메타는 추천·광고 타겟팅·행동 예측을 하루 2조 건 넘게 돌린다는 추정이 있는데, 여기에 만능 GPU를 쓰는 건 과잉이다.',
