        '<b>불량의 대가가 크다.</b> 맨 위층에서 불량이 나면 아래 멀쩡한 층까지 통째로 버린다. 12층짜리의 마지막에서 실수가 나면 정상이던 11개 층이 다 날아간다. 합치면 같은 용량에 웨이퍼가 <b>3~4배</b> 들고, 다음 세대로 갈수록 4배 가까이 더 벌어진다.',
