        '<b>진짜 해자는 전환비용이다.</b> 검사 장비는 그 공장이 몇 달에 걸쳐 쌓은 결함 통계를 갖고 있어서, 다른 회사 것으로 바꾸면 그 데이터가 초기화되고 수백억 원의 손실이 난다.',
